/**
 * Holo family pop-reverse: the reverse faces of POP Series 6-9 (reverse round, 2026-11-28).
 *
 * Scope: every reverse face of pop6-pop9 (68 faces), which the dp-reverse family leaves out (POP packs dealt no
 * reverse; the game data has the faces). They sat on dp.css's Mirror, whose 1.5-5% spectrum stripes read as straight
 * vertical rainbow bars over the frame and the text at phone size (2026-11-28 reverse review: 11 of 12 bad). POP 1-5
 * (the EX mirror, wider bands) passed and are not claimed.
 *
 * What it adds (css/holo/fam/pop-reverse.css, generated by scripts/fam/mirror-reverse/make_sheets.py):
 *   fam-pop-reverse   every face it claims.
 *   --pr-mask         where the face is foil: the dp-reverse family's own frame mask of the layout
 *                     (assets/foil/fam/dp-reverse/dp-<basic|stage|trainer|senergy>.webp: the face inside the yellow
 *                     border less the picture and the evolution circle).
 *
 * Never import js/foil-maps.js from here (it waits on this module).
 */
import { isDp } from "../dp-foil.js?v=3";

/** The mask's layout (as js/fam/dp-reverse.js names them). */
function layout(card) {
  const subs = card.subtypes || [];
  if (card.supertype === "Trainer") return "trainer";
  if (card.supertype === "Energy" || card.energy) return "senergy";
  return subs.includes("Stage 1") || subs.includes("Stage 2") || card.evolvesFrom ? "stage" : "basic";
}

/** Whether a card face is this family's: a reverse of POP Series 6-9. */
export function claims(card) {
  return Boolean(card?.reverse) && /^pop[6-9]-/.test(String(card.id || "")) && isDp(card);
}

export function famExtras(card, url) {
  if (!claims(card)) return null;
  return {
    classes: "fam-pop-reverse",
    style: `--pr-mask:url('${url(`assets/foil/fam/dp-reverse/dp-${layout(card)}.webp`)}')`,
    cure: false,
  };
}
